function expenseTotal(rows){return rows.reduce((a,s)=>a+s.amount,0)}
function commissionFor(sale){return Math.round(sale.total*(sale.commission??db.barbers.find(b=>b.id===sale.barberId)?.commission??db.settings.commission)/100)}
function canConsumeForSale(items){const required=new Map();for(const line of items){const s=db.services.find(x=>x.id===line.serviceId);for(const r of s?.consumables||[])required.set(r.consumableId,(required.get(r.consumableId)||0)+Number(r.quantity||0))}for(const [id,qty] of required){const c=db.consumables.find(x=>x.id===id);if(!c||!c.active)return {ok:false,message:`المستهلك المرتبط بالخدمة غير متاح: ${consumableName(id)}`};if(c.stock+1e-9<qty)return {ok:false,message:`رصيد ${c.name} غير كافٍ؛ المطلوب ${qty} ${c.unit} والمتاح ${c.stock}`} }return {ok:true}}
function consumeForSale(items,sale){for(const line of items){const s=db.services.find(x=>x.id===line.serviceId);for(const r of s?.consumables||[]){const c=db.consumables.find(x=>x.id===r.consumableId),qty=Number(r.quantity)||0;if(!c||qty<=0)continue;c.stock=Math.max(0,c.stock-qty);db.stockMovements.push({id:uid(),date:sale.date,type:'استهلاك',consumableId:c.id,quantity:qty,unitCost:c.unitCost||0,amount:qty*(c.unitCost||0),saleId:sale.id,serviceId:s.id,note:`استهلاك تلقائي - ${s.name}`})}}}
function salesRows(rows){if(!rows.length)return `<div class="empty-state">لا توجد عمليات حتى الآن</div>`;return `<div class="table-wrap"><table class="data-table"><thead><tr><th>الوقت</th><th>العميل</th><th>الخدمات</th><th>الحلاق</th><th>طريقة الدفع</th><th>الإجمالي</th></tr></thead><tbody>${rows.slice().sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).map(s=>`<tr><td>${timeFmt(s.createdAt)}</td><td>${esc(s.client||'عميل نقدي')}</td><td>${s.items.map(i=>esc(serviceName(i.serviceId))).join('، ')}</td><td>${esc(barberName(s.barberId))}</td><td><span class="tag gray">${s.payment==='cash'?'نقدي':'بطاقة'}</span></td><td class="amount">${money(s.total)}</td></tr>`).join('')}</tbody></table></div>`}
function applyRoleUi(){document.querySelectorAll('.nav-item[data-page]').forEach(b=>{b.style.display=canAccessPage(b.dataset.page)?'':'none'});document.querySelectorAll('.section-label').forEach(x=>x.style.display=isManager()?'':'none');const name=currentUser?.name||'مدير النظام',role=currentUser?.role==='admin'?'أدمن النظام':currentUser?.role==='manager'?'مدير':'كاشير';document.querySelector('#profileBtn strong').textContent=name;document.querySelector('#profileBtn small').textContent=role;document.querySelector('#profileBtn .profile-pic').textContent=name[0]||'م';document.querySelector('.top-avatar').textContent=name[0]||'م';document.getElementById('backupBtn').style.display=isAdmin()?'':'none';document.getElementById('excelIndicator').style.display=isAdmin()?'':'none'}
function render(){applyRoleUi();if(!canAccessPage(page))page=isManager()?'dashboard':'cashier';document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===page));document.getElementById('crumb').textContent=pageNames[page];document.getElementById('navOpen').textContent=db.closes.some(c=>c.date===today)?'مغلق':'مفتوح';const el=document.getElementById('page');el.innerHTML=({dashboard:dashboardPage,cashier:cashierPage,appointments:appointmentsPage,customers:customersPage,barbers:barbersPage,services:servicesPage,consumables:consumablesPage,chairs:chairsPage,expenses:expensesPage,reports:reportsPage,settings:settingsPage,users:usersPage}[page]||dashboardPage)();wirePage();if(excelSyncing)setExcelStatus('connected','Excel محفوظ')}
function dashboardPage(){const sales=todaySales(),total=salesTotal(sales),expenses=expenseTotal(db.expenses.filter(e=>e.date===today)),counts={};sales.forEach(s=>counts[s.barberId]=(counts[s.barberId]||0)+1);const performance=activeBarbers().map(b=>({b,count:counts[b.id]||0,earn:sales.filter(s=>s.barberId===b.id).reduce((a,s)=>a+commissionFor(s),0)}));const max=Math.max(1,...performance.map(x=>x.count));return `<div class="dashboard-toolbar"><button class="btn btn-primary" data-action="go-cashier">＋ عملية بيع جديدة</button></div>${excelNotice()}
<div class="grid stats-grid">${stat('إيرادات اليوم',money(total),'↗',`<span class="positive">${sales.length} عملية بيع</span> اليوم`)}${stat('صافي المحل',money(total-expenses-sales.reduce((a,s)=>a+commissionFor(s),0)),'◈','بعد المصروفات وأتعاب الحلاقين')}${stat('العملاء اليوم',sales.reduce((a,s)=>a+(s.customers||1),0),'♙','عميل تم خدمتهم')}${stat('مصروفات اليوم',money(expenses),'↙',`${db.expenses.filter(e=>e.date===today).length} مصروف مسجل`)}</div>
<div class="grid dashboard-grid"><div class="card panel"><div class="panel-header"><div><h2>آخر العمليات</h2><p>مبيعات اليوم المسجلة على الكاشير</p></div><button class="text-link" data-action="go-cashier">فتح الكاشير ←</button></div>${salesRows(sales.slice(-6))}</div><div class="card panel"><div class="panel-header"><div><h2>أداء الحلاقين</h2><p>عدد العملاء وأتعاب اليوم</p></div><button class="text-link" data-action="go-barbers">التفاصيل ←</button></div><div class="barber-performance">${performance.length?performance.map(({b,count,earn})=>`<div class="barber-line"><div class="barber-avatar">${esc(b.name[0])}</div><div class="barber-info"><strong>${esc(b.name)}</strong><small>${count} عميل · ${money(earn)} أتعاب</small><div class="progress"><span style="width:${Math.max(4,count/max*100)}%"></span></div></div><div class="barber-total">${count}</div></div>`).join(''):'<div class="empty-state">أضف حلاقين لعرض الأداء</div>'}</div></div></div>
<div class="card panel" style="margin-top:15px"><div class="panel-header"><div><h2>حالة الكراسي</h2><p>نظرة سريعة على كراسي المحل</p></div><button class="text-link" data-action="go-chairs">إدارة الكراسي ←</button></div><div class="chairs-grid" style="grid-template-columns:repeat(4,1fr);margin-bottom:0">${db.chairs.filter(c=>c.active).map(c=>{const used=sales.some(s=>s.chairId===c.id&&s.date===today);return `<div class="card chair-card"><div class="chair-top"><strong>${esc(c.name)}</strong><span class="chair-icon">▤</span></div><div class="chair-status ${used?'busy':'free'}">● ${used?'تم استخدامه اليوم':'متاح'}</div></div>`}).join('')||'<div class="empty-state">لا توجد كراسي</div>'}</div></div>`}
function cashierPage(){const isClosed=db.closes.some(c=>c.date===today);return `${pageHead('الكاشير','سجّل الخدمات، حدّد الحلاق والكرسي، ثم احفظ عملية البيع.',isClosed?'<span class="tag red">الكاشير مغلق اليوم</span>':`<button class="btn" data-action="close-day">▣ إقفال اليوم</button>`)}<div class="split-layout"><div><div class="card panel"><div class="panel-header"><div><h2>الخدمات</h2><p>اضغط على الخدمة لإضافتها للفاتورة</p></div><input class="input" id="serviceSearch" placeholder="ابحث عن خدمة..." style="width:190px" /></div><div class="cashier-services" id="serviceTiles">${db.services.filter(s=>s.active).map(s=>`<button class="service-tile" data-add-service="${s.id}"><span class="tile-icon">✦</span><strong>${esc(s.name)}</strong><small>${money(s.price)} · ${s.minutes} دقيقة</small></button>`).join('')||'<div class="empty-state">أضف الخدمات من صفحة الإدارة</div>'}</div></div><div class="card panel" style="margin-top:14px"><div class="panel-header"><div><h2>آخر عمليات اليوم</h2><p>المبيعات المسجلة حتى الآن</p></div><span class="tag">${todaySales().length} عملية</span></div>${salesRows(todaySales())}</div></div><div class="card panel order-card"><div class="panel-header"><div><h2>فاتورة جديدة</h2><p>بيانات العميل والخدمة</p></div><button class="text-link" data-action="clear-cart">تفريغ</button></div><div class="form-grid"><div class="field"><label>اسم العميل (اختياري)</label><input id="clientName" class="input" placeholder="عميل نقدي" /></div><div class="field"><label>رقم الهاتف (اختياري)</label><input id="clientPhone" class="input" placeholder="01xxxxxxxxx" /></div><div class="field"><label>الحلاق</label><select id="saleBarber" class="select"><option value="">اختر الحلاق</option>${activeBarbers().map(b=>`<option value="${b.id}">${esc(b.name)} · ${b.commission}%</option>`).join('')}</select></div><div class="field"><label>الكرسي</label><select id="saleChair" class="select"><option value="">اختر الكرسي</option>${db.chairs.filter(c=>c.active).map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div></div><div id="cartRows">${cartHtml()}</div><div class="order-total"><span>الإجمالي</span><strong>${money(cart.reduce((a,i)=>a+i.price,0))}</strong></div><div class="field"><label>طريقة الدفع</label><select id="salePayment" class="select"><option value="cash">نقدي</option><option value="card">بطاقة</option></select></div><button class="btn btn-primary" data-action="checkout" ${isClosed?'disabled':''} style="width:100%;margin-top:14px">تأكيد البيع · ${money(cart.reduce((a,i)=>a+i.price,0))}</button><div class="hint" style="margin-top:9px">أتعاب الحلاق: <b>حسب النسبة المحددة لكل حلاق</b></div></div></div>`}
function cartHtml(){return cart.length?cart.map((i,n)=>`<div class="order-row"><div>${esc(i.name)}<small>${money(i.price)}</small></div><b>${money(i.price)}</b><button class="remove-line" data-remove-item="${n}">×</button></div>`).join(''):'<div class="empty-state" style="padding:20px 8px">الفاتورة فارغة<br>اختر خدمة من القائمة</div>'}
function appointmentsPage(){return `${pageHead('الحجوزات','سجّل مواعيد العملاء وتابع حالة كل حجز.',`<button class="btn btn-primary" data-action="new-appointment">＋ حجز جديد</button>`)}<div class="card panel"><div class="panel-header"><div><h2>حجوزات اليوم</h2><p>${dateFmt(today)}</p></div><span class="tag">${db.appointments.filter(a=>a.date===today&&a.status!=='cancelled').length} حجوزات</span></div>${appointmentTable(db.appointments.filter(a=>a.date===today))}</div><div class="card panel" style="margin-top:15px"><div class="panel-header"><div><h2>كل الحجوزات</h2><p>السجل الكامل للمواعيد</p></div></div>${appointmentTable(db.appointments.slice().sort((a,b)=>b.date.localeCompare(a.date)))}</div>`}
function appointmentTable(rows){if(!rows.length)return'<div class="empty-state">لا توجد حجوزات مسجلة</div>';return `<div class="table-wrap"><table class="data-table"><thead><tr><th>التاريخ والوقت</th><th>العميل</th><th>الخدمة</th><th>الحلاق</th><th>الهاتف</th><th>الحالة</th><th></th></tr></thead><tbody>${rows.map(a=>`<tr><td>${dateFmt(a.date)} · ${esc(a.time)}</td><td>${esc(a.client)}</td><td>${esc(serviceName(a.serviceId))}</td><td>${esc(barberName(a.barberId))}</td><td>${esc(a.phone||'—')}</td><td><span class="tag ${a.status==='completed'?'':'orange'}">${a.status==='completed'?'مكتمل':a.status==='cancelled'?'ملغي':'قادم'}</span></td><td>${a.status==='booked'?`<button class="btn btn-small btn-soft" data-complete-appt="${a.id}">تم الحضور</button> <button class="btn btn-small" data-cancel-appt="${a.id}">إلغاء</button>`:''}</td></tr>`).join('')}</tbody></table></div>`}
function customerGroups(){const groups=new Map();for(const s of db.sales){const name=(s.client||'').trim();if(!name||name==='عميل نقدي')continue;const phone=(s.clientPhone||'').replace(/\D/g,'');const key=phone?'p:'+phone:'n:'+name.toLocaleLowerCase();if(!groups.has(key))groups.set(key,{key,name,phone:s.clientPhone||'',sales:[]});const g=groups.get(key);g.sales.push(s);if(!g.phone&&s.clientPhone)g.phone=s.clientPhone}return [...groups.values()].sort((a,b)=>b.sales.length-a.sales.length)}
function customersPage(){const rows=customerGroups();return `${pageHead('العملاء','تاريخ زيارات العملاء والخدمات التي حصلوا عليها.')}<div class="grid stats-grid" style="grid-template-columns:repeat(3,1fr)">${stat('العملاء المسجلون',rows.length,'♙','حسب الاسم ورقم الهاتف')}${stat('زيارات مسجلة',db.sales.filter(s=>s.client&&s.client!=='عميل نقدي').length,'◷','من كل الفترات')}${stat('إنفاق العملاء',money(rows.reduce((a,c)=>a+salesTotal(c.sales),0)),'◈','إجمالي فواتيرهم')}</div><div class="card panel"><div class="panel-header"><div><h2>سجل العملاء</h2><p>اضغط على العميل لعرض سجل زياراته</p></div><input id="customerSearch" class="input" placeholder="ابحث بالاسم أو الهاتف" style="width:200px" /></div><div class="table-wrap"><table class="data-table"><thead><tr><th>العميل</th><th>الهاتف</th><th>عدد الزيارات</th><th>إجمالي الإنفاق</th><th>آخر زيارة</th><th></th></tr></thead><tbody>${rows.length?rows.map(c=>`<tr class="history-row"><td><strong>${esc(c.name)}</strong></td><td>${esc(c.phone||'—')}</td><td>${c.sales.length}</td><td class="amount">${money(salesTotal(c.sales))}</td><td>${dateFmt(c.sales.reduce((a,s)=>s.date>a?s.date:a,''))}</td><td><button class="btn btn-small" data-customer-history="${esc(c.key)}">عرض السجل</button></td></tr>`).join(''):'<tr><td colspan="6" class="empty-state">تُسجّل الزيارات في الكاشير عند إدخال اسم العميل ورقم هاتفه</td></tr>'}</tbody></table></div></div>`}
function customerHistory(key){const c=customerGroups().find(x=>x.key===key);if(!c)return;showModal('سجل '+esc(c.name),`<div class="modal-note">${esc(c.phone||'بدون رقم هاتف')} · ${c.sales.length} زيارة · إجمالي ${money(salesTotal(c.sales))}</div>${salesRows(c.sales)}`,closeAction('إغلاق'))}
function barberPeriodSales(id,period){return db.sales.filter(s=>s.barberId===id&&s.date.startsWith(period))}
function barberPeriodPaid(id,period){return db.payouts.filter(p=>p.barberId===id&&(p.period||p.date.slice(0,7))===period&&p.note!=='صرف راتب').reduce((a,p)=>a+Number(p.amount||0),0)}
function barbersPage(){const monthSales=db.sales.filter(s=>s.date.startsWith(reportMonth)),fees=monthSales.reduce((a,s)=>a+commissionFor(s),0),paid=db.payouts.filter(p=>(p.period||p.date.slice(0,7))===reportMonth&&p.note!=='صرف راتب').reduce((a,p)=>a+Number(p.amount||0),0),due=Math.max(0,fees-paid);return `${pageHead('الحلاقين','إدارة الفريق ونسبة العمولة ومتابعة المستحق والمدفوع.',`<button class="btn btn-primary" data-action="add-barber">＋ إضافة حلاق</button>`)}<div class="month-summary" style="grid-template-columns:repeat(4,1fr)">${stat('عدد الحلاقين',activeBarbers().length,'♙','حلاق نشط')}${stat('أتعاب مستحقة',money(fees),'◈','عن الشهر المحدد')}${stat('أتعاب مدفوعة',money(paid),'✓','عن الشهر المحدد')}${stat('متبقي للصرف',money(due),'◷','رصيد الحلاقين')}</div><div class="card panel"><div class="panel-header"><div><h2>فريق العمل</h2><p>النسبة تُحسب من قيمة الخدمات. سجّل الصرف كليًا أو على دفعات.</p></div><input class="input" type="month" id="barberMonth" value="${reportMonth}" style="width:150px" /></div><div class="table-wrap"><table class="data-table"><thead><tr><th>الحلاق</th><th>الهاتف</th><th>العمولة</th><th>عملاء الشهر</th><th>مبيعات الشهر</th><th>مستحق</th><th>مدفوع</th><th>متبقي</th><th></th></tr></thead><tbody>${db.barbers.map(b=>{const rows=barberPeriodSales(b.id,reportMonth),fee=rows.reduce((a,s)=>a+commissionFor(s),0),paidBarber=barberPeriodPaid(b.id,reportMonth),remaining=Math.max(0,fee-paidBarber);return `<tr><td><strong>${esc(b.name)}</strong></td><td>${esc(b.phone||'—')}</td><td>${b.commission}%</td><td>${rows.length}</td><td>${money(salesTotal(rows))}</td><td>${money(fee)}</td><td>${money(paidBarber)}</td><td class="amount">${money(remaining)}</td><td><button class="btn btn-small ${remaining?'btn-soft':''}" data-payout-barber="${b.id}" ${remaining?'':'disabled'}>صرف أتعاب</button> <button class="btn btn-small" data-edit-barber="${b.id}">تعديل</button></td></tr>`}).join('')}</tbody></table></div></div><div class="card panel" style="margin-top:15px"><div class="panel-header"><div><h2>سجل صرف الأتعاب</h2><p>المدفوعات المسجلة للشهر المحدد</p></div></div>${payoutTable(db.payouts.filter(p=>(p.period||p.date.slice(0,7))===reportMonth))}</div>`}
function payoutTable(rows){if(!rows.length)return'<div class="empty-state">لا توجد مدفوعات أتعاب في هذه الفترة</div>';return `<div class="table-wrap"><table class="data-table"><thead><tr><th>تاريخ الصرف</th><th>عن شهر</th><th>الحلاق</th><th>طريقة الدفع</th><th>المبلغ</th><th>ملاحظات</th></tr></thead><tbody>${rows.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(p=>`<tr><td>${dateFmt(p.date)}</td><td>${esc(p.period||p.date.slice(0,7))}</td><td>${esc(barberName(p.barberId))}</td><td>${p.payment==='cash'?'نقدي':p.payment==='wallet'?'محفظة إلكترونية':p.payment==='other'?'أخرى':'بطاقة'}</td><td class="amount">${money(p.amount)}</td><td>${esc(p.note||'—')}</td></tr>`).join('')}</tbody></table></div>`}
function payoutModal(barberId){const b=db.barbers.find(x=>x.id===barberId),fee=barberPeriodSales(barberId,reportMonth).reduce((a,s)=>a+commissionFor(s),0),paid=barberPeriodPaid(barberId,reportMonth),remaining=Math.max(0,fee-paid);if(!remaining)return toast('لا توجد أتعاب متبقية لهذا الحلاق في الشهر المحدد');showModal('صرف أتعاب '+esc(b.name),`<div class="modal-note">المستحق: ${money(fee)} · المدفوع: ${money(paid)} · المتبقي: <b>${money(remaining)}</b></div><form id="entityForm"><div class="form-grid"><div class="field"><label>المبلغ *</label><input name="amount" class="input" type="number" min="1" max="${remaining}" value="${remaining}" required /></div><div class="field"><label>عن شهر</label><input name="period" class="input" type="month" value="${reportMonth}" readonly /></div><div class="field"><label>تاريخ الصرف</label><input name="date" class="input" type="date" value="${today}" required /></div><div class="field"><label>طريقة الدفع</label><select name="payment" class="select"><option value="cash">نقدي</option><option value="card">تحويل / بطاقة</option></select></div><div class="field full"><label>ملاحظات</label><input name="note" class="input" /></div></div></form>`,`<button class="btn" onclick="closeModal()">إلغاء</button><button class="btn btn-primary" id="savePayout">تسجيل الصرف</button>`);document.getElementById('savePayout').onclick=()=>{const f=new FormData(document.getElementById('entityForm')),amount=Number(f.get('amount'));if(!Number.isFinite(amount)||amount<=0||amount>remaining)return toast('المبلغ أكبر من المتبقي أو غير صالح');if(db.closes.some(c=>c.date===f.get('date')))return toast('اليوم المختار مقفل');db.payouts.push({id:uid(),barberId,amount,period:reportMonth,date:f.get('date'),payment:f.get('payment'),note:String(f.get('note')||'').trim()});save();closeModal();render();toast('تم تسجيل صرف الأتعاب')}}
function servicesPage(){return `${pageHead('الخدمات','أضف خدمات المحل واضبط أسعارها ومدتها.',`<button class="btn btn-primary" data-action="add-service">＋ إضافة خدمة</button>`)}<div class="card panel"><div class="panel-header"><div><h2>قائمة الخدمات</h2><p>${db.services.filter(s=>s.active).length} خدمات متاحة للكاشير</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>الخدمة</th><th>السعر</th><th>المدة المتوقعة</th><th>الحالة</th><th></th></tr></thead><tbody>${db.services.map(s=>`<tr><td><strong>${esc(s.name)}</strong></td><td class="amount">${money(s.price)}</td><td>${s.minutes} دقيقة</td><td><span class="tag ${s.active?'':'gray'}">${s.active?'متاحة':'موقوفة'}</span></td><td><button class="btn btn-small" data-edit-service="${s.id}">تعديل</button> <button class="btn btn-small btn-soft" data-recipe-service="${s.id}">مستهلكات الخدمة</button></td></tr>`).join('')}</tbody></table></div></div>`}
function consumableName(id){return db.consumables.find(c=>c.id===id)?.name||'صنف محذوف'}
function stockMovementsTable(rows){if(!rows.length)return'<div class="empty-state">لا توجد حركات مخزون مسجلة</div>';return `<div class="table-wrap"><table class="data-table"><thead><tr><th>التاريخ</th><th>الحركة</th><th>الصنف</th><th>الكمية</th><th>التكلفة</th><th>الخدمة / الملاحظة</th></tr></thead><tbody>${rows.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,30).map(m=>`<tr><td>${dateFmt(m.date)}</td><td><span class="tag ${m.type==='شراء'?'':'orange'}">${esc(m.type)}</span></td><td>${esc(consumableName(m.consumableId))}</td><td>${m.quantity} ${esc(db.consumables.find(c=>c.id===m.consumableId)?.unit||'')}</td><td>${money(m.amount||0)}</td><td>${esc(m.serviceId?serviceName(m.serviceId):m.note||'—')}</td></tr>`).join('')}</tbody></table></div>`}
function consumablesPage(){const active=db.consumables.filter(c=>c.active),low=active.filter(c=>c.minStock>0&&c.stock<=c.minStock),value=active.reduce((a,c)=>a+c.stock*c.unitCost,0),purchases=db.stockMovements.filter(m=>m.type==='شراء');return `${pageHead('المستهلكات','تابع الرصيد، سجّل المشتريات، واضبط استهلاك كل خدمة.',`<div class="inline-add"><button class="btn" data-action="add-consumable">＋ صنف جديد</button><button class="btn btn-primary" data-action="purchase-consumable">＋ شراء مستهلكات</button></div>`)}<div class="grid stats-grid" style="grid-template-columns:repeat(4,1fr)">${stat('أصناف نشطة',active.length,'▦','مستهلكات مسجلة')}${stat('قيمة المخزون',money(value),'◈','حسب متوسط تكلفة الشراء')}${stat('أصناف منخفضة',low.length,'!','عند حد إعادة الطلب')}${stat('مشتريات مسجلة',purchases.length,'↙','كل حركة شراء تسجل كمصروف')}</div>${low.length?`<div class="close-banner"><div><strong>تنبيه مخزون منخفض</strong><small>${low.map(c=>`${esc(c.name)} (${c.stock} ${esc(c.unit)})`).join(' · ')}</small></div><span class="tag orange">${low.length} أصناف</span></div>`:''}<div class="card panel"><div class="panel-header"><div><h2>رصيد المستهلكات</h2><p>الخصم يتم تلقائيًا عند بيع خدمة مرتبطة بصنف</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>الصنف</th><th>الوحدة</th><th>الرصيد</th><th>حد التنبيه</th><th>متوسط تكلفة الوحدة</th><th>القيمة</th><th>الحالة</th><th></th></tr></thead><tbody>${db.consumables.length?db.consumables.map(c=>`<tr><td><strong>${esc(c.name)}</strong></td><td>${esc(c.unit)}</td><td class="amount">${c.stock}</td><td>${c.minStock}</td><td>${money(c.unitCost)}</td><td>${money(c.stock*c.unitCost)}</td><td><span class="tag ${c.minStock>0&&c.stock<=c.minStock?'orange':'gray'}">${c.minStock>0&&c.stock<=c.minStock?'منخفض':'متاح'}</span></td><td><button class="btn btn-small" data-edit-consumable="${c.id}">تعديل</button></td></tr>`).join(''):'<tr><td colspan="8" class="empty-state">أضف أصناف المستهلكات ثم سجّل مشترياتها</td></tr>'}</tbody></table></div></div><div class="card panel" style="margin-top:15px"><div class="panel-header"><div><h2>آخر حركات المخزون</h2><p>شراء المستهلكات واستهلاكها في الخدمات</p></div></div>${stockMovementsTable(db.stockMovements)}</div>`}
function recipeModal(serviceId){const s=db.services.find(x=>x.id===serviceId);if(!s)return;let recipe=[...(s.consumables||[])];const rowHtml=r=>`<div class="recipe-row form-grid" style="grid-template-columns:1fr 120px 32px;align-items:end;margin:8px 0"><div class="field"><label>الصنف</label><select class="select recipe-item"><option value="">اختر مستهلكًا</option>${db.consumables.filter(c=>c.active).map(c=>`<option value="${c.id}" ${r?.consumableId===c.id?'selected':''}>${esc(c.name)} · ${esc(c.unit)}</option>`).join('')}</select></div><div class="field"><label>الكمية لكل خدمة</label><input class="input recipe-quantity" type="number" min="0.001" step="0.001" value="${r?.quantity||''}" /></div><button class="btn btn-small btn-danger remove-recipe" type="button">×</button></div>`;showModal('مستهلكات خدمة '+esc(s.name),`<div class="modal-note">تُخصم هذه الكميات تلقائيًا عند تسجيل الخدمة في الكاشير. قيمة الشراء تُسجّل مصروفًا عند إدخال المشتريات، ولا تُسجّل كمصروف مرة أخرى عند الاستهلاك.</div><div id="recipeRows">${recipe.map(rowHtml).join('')||'<div class="empty-state" style="padding:15px">لا توجد أصناف مرتبطة بهذه الخدمة</div>'}</div><button class="btn" id="addRecipeRow">＋ إضافة صنف</button>`,`<button class="btn" onclick="closeModal()">إلغاء</button><button class="btn btn-primary" id="saveRecipe">حفظ إعداد الاستهلاك</button>`);const bind=()=>document.querySelectorAll('.remove-recipe').forEach(b=>b.onclick=()=>{b.closest('.recipe-row').remove();if(!document.querySelector('.recipe-row'))document.getElementById('recipeRows').innerHTML='<div class="empty-state" style="padding:15px">لا توجد أصناف مرتبطة بهذه الخدمة</div>'});document.getElementById('addRecipeRow').onclick=()=>{const box=document.getElementById('recipeRows');if(!document.querySelector('.recipe-row'))box.innerHTML='';box.insertAdjacentHTML('beforeend',rowHtml(null));bind()};bind();document.getElementById('saveRecipe').onclick=()=>{const next=[...document.querySelectorAll('.recipe-row')].map(r=>({consumableId:r.querySelector('.recipe-item').value,quantity:Number(r.querySelector('.recipe-quantity').value)})).filter(r=>r.consumableId&&r.quantity>0);s.consumables=next;save();closeModal();render();toast('تم حفظ مستهلكات الخدمة')}}
function consumableModal(id){const c=db.consumables.find(x=>x.id===id)||{name:'',unit:'وحدة',minStock:0,active:true};showModal(id?'تعديل الصنف':'إضافة مستهلك جديد',`<form id="entityForm"><div class="form-grid"><div class="field full"><label>اسم المستهلك *</label><input name="name" class="input" required value="${esc(c.name)}" placeholder="مثال: شفرة حلاقة" /></div><div class="field"><label>وحدة القياس</label><input name="unit" class="input" value="${esc(c.unit)}" placeholder="قطعة / مل / جرام" /></div><div class="field"><label>حد التنبيه عند انخفاض الرصيد</label><input name="minStock" class="input" type="number" min="0" step="0.001" value="${c.minStock||0}" /></div><div class="field full"><label class="inline-add"><input name="active" type="checkbox" ${c.active?'checked':''}/> الصنف نشط ويمكن ربطه بالخدمات</label></div></div></form>`,`<button class="btn" onclick="closeModal()">إلغاء</button><button class="btn btn-primary" id="saveEntity">حفظ الصنف</button>`);document.getElementById('saveEntity').onclick=()=>{const f=new FormData(document.getElementById('entityForm'));if(!f.get('name').trim())return;const data={id:id||uid(),name:f.get('name').trim(),unit:f.get('unit').trim()||'وحدة',minStock:Number(f.get('minStock'))||0,active:f.has('active'),stock:c.stock||0,unitCost:c.unitCost||0};if(id)Object.assign(c,data);else db.consumables.push(data);save();closeModal();render();toast('تم حفظ المستهلك')}}
function purchaseConsumableModal(){if(db.closes.some(c=>c.date===today))return toast('اليوم مقفل؛ لا يمكن إضافة مصروف شراء بتاريخ اليوم');if(!db.consumables.some(c=>c.active))return consumableModal();showModal('شراء مستهلكات',`<div class="modal-note">يسجل مبلغ الشراء كمصروف في نفس اللحظة، ويضيف الكمية إلى المخزون.</div><form id="entityForm"><div class="form-grid"><div class="field full"><label>الصنف *</label><select name="consumableId" id="purchaseItem" class="select">${db.consumables.filter(c=>c.active).map(c=>`<option value="${c.id}">${esc(c.name)} · الرصيد ${c.stock} ${esc(c.unit)}</option>`).join('')}</select></div><div class="field"><label>الكمية المشتراة *</label><input name="quantity" class="input" type="number" min="0.001" step="0.001" required /></div><div class="field"><label>تكلفة الوحدة *</label><input name="unitCost" class="input" type="number" min="0" step="0.01" required /></div><div class="field"><label>تاريخ الشراء</label><input name="date" class="input" type="date" value="${today}" required /></div><div class="field"><label>طريقة الدفع</label><select name="payment" class="select"><option value="cash">نقدي</option><option value="card">بطاقة / تحويل</option></select></div><div class="field full"><label>ملاحظات أو المورد</label><input name="note" class="input" /></div></div><div class="hint">إجمالي المصروف: <b id="purchaseTotal">0</b></div></form>`,`<button class="btn" onclick="closeModal()">إلغاء</button><button class="btn btn-primary" id="savePurchase">تسجيل الشراء والمصروف</button>`);const updateTotal=()=>{const f=new FormData(document.getElementById('entityForm'));document.getElementById('purchaseTotal').textContent=money((Number(f.get('quantity'))||0)*(Number(f.get('unitCost'))||0))};document.getElementById('entityForm').oninput=updateTotal;document.getElementById('savePurchase').onclick=()=>{const f=new FormData(document.getElementById('entityForm')),item=db.consumables.find(c=>c.id===f.get('consumableId')),qty=Number(f.get('quantity')),cost=Number(f.get('unitCost')),date=f.get('date');if(!item||qty<=0||cost<0)return toast('أدخل الصنف والكمية والتكلفة بشكل صحيح');if(date===today&&db.closes.some(c=>c.date===today))return toast('اليوم مقفل');const amount=qty*cost,oldStock=item.stock,expenseId=uid();item.unitCost=((oldStock*item.unitCost)+(qty*cost))/(oldStock+qty);item.stock+=qty;db.expenses.push({id:expenseId,title:`شراء ${item.name}`,amount,category:'مستهلكات',date,payment:f.get('payment'),note:f.get('note').trim()});db.stockMovements.push({id:uid(),date,type:'شراء',consumableId:item.id,quantity:qty,unitCost:cost,amount,expenseId,note:f.get('note').trim()});save();closeModal();render();toast('تمت إضافة الكمية وتسجيلها كمصروف')}}
function chairsPage(){return `${pageHead('الكراسي','أدر كراسي المحل واعرف مرات استخدامها.',`<button class="btn btn-primary" data-action="add-chair">＋ إضافة كرسي</button>`)}<div class="chairs-grid">${db.chairs.map(c=>`<div class="card chair-card"><div class="chair-top"><strong>${esc(c.name)}</strong><span class="chair-icon">▤</span></div><div class="chair-status ${c.active?'free':'off'}">● ${c.active?'نشط':'موقوف'}</div><div style="margin-top:13px;display:flex;justify-content:space-between;align-items:center"><span class="muted" style="font-size:8px">استخدم ${db.sales.filter(s=>s.chairId===c.id).length} مرة</span><button class="btn btn-small" data-edit-chair="${c.id}">تعديل</button></div></div>`).join('')}</div>`}
function expensesPage(){const rows=db.expenses.filter(e=>e.date===today);return `${pageHead('المصروفات','سجّل مصروفات المحل وراجع تفاصيلها.',`<button class="btn btn-primary" data-action="add-expense">＋ تسجيل مصروف</button>`)}<div class="grid stats-grid" style="grid-template-columns:repeat(3,1fr)">${stat('مصروفات اليوم',money(expenseTotal(rows)),'↙',`${rows.length} بند`)}${stat('مصروفات الشهر',money(expenseTotal(db.expenses.filter(e=>e.date.startsWith(today.slice(0,7))))),'▤','من بداية الشهر')}${stat('كل المصروفات',money(expenseTotal(db.expenses)),'◈','منذ بدء الاستخدام')}</div><div class="card panel"><div class="panel-header"><div><h2>سجل المصروفات</h2><p>جميع المصروفات المسجلة</p></div><select class="select" id="expenseMonth" style="width:145px"><option value="all">كل الفترات</option>${[...new Set(db.expenses.map(e=>e.date.slice(0,7)))].sort().reverse().map(m=>`<option value="${m}">${m}</option>`).join('')}</select></div><div id="expenseTable">${expenseTable(db.expenses)}</div></div>`}
function expenseTable(rows){if(!rows.length)return'<div class="empty-state">لا توجد مصروفات مسجلة</div>';return `<div class="table-wrap"><table class="data-table"><thead><tr><th>التاريخ</th><th>البند</th><th>التصنيف</th><th>طريقة الدفع</th><th>المبلغ</th><th>ملاحظات</th><th></th></tr></thead><tbody>${rows.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(e=>`<tr><td>${dateFmt(e.date)}</td><td><strong>${esc(e.title)}</strong></td><td><span class="tag gray">${esc(e.category)}</span></td><td>${e.payment==='cash'?'نقدي':e.payment==='wallet'?'محفظة إلكترونية':e.payment==='other'?'أخرى':'بطاقة'}</td><td class="amount">${money(e.amount)}</td><td>${esc(e.note||'—')}</td><td><button class="btn btn-small btn-danger" data-delete-expense="${e.id}">حذف</button></td></tr>`).join('')}</tbody></table></div>`}
function reportDateInRange(date){return (!reportFilters.from||date>=reportFilters.from)&&(!reportFilters.to||date<=reportFilters.to)}
function reportSearchMatches(query,...values){if(!query)return true;const q=query.toLocaleLowerCase();return values.some(v=>String(v??'').toLocaleLowerCase().includes(q))}
function buildReportData(){const f=reportFilters,q=(f.query||'').trim(),sales=[];for(const sale of db.sales){if(!reportDateInRange(sale.date)||(f.barberId&&sale.barberId!==f.barberId)||(f.payment&&sale.payment!==f.payment))continue;const barber=barberName(sale.barberId),pay=sale.payment==='cash'?'نقدي':sale.payment==='card'?'بطاقة':sale.payment==='wallet'?'محفظة إلكترونية':'أخرى';for(const item of sale.items||[]){const service=db.services.find(x=>x.id===item.serviceId);if(f.serviceId&&item.serviceId!==f.serviceId)continue;if(f.consumableId&&!(service?.consumables||[]).some(x=>x.consumableId===f.consumableId))continue;const recipeNames=(service?.consumables||[]).map(x=>consumableName(x.consumableId)).join(' ');if(!reportSearchMatches(q,sale.client,sale.clientPhone,barber,service?.name,recipeNames,chairName(sale.chairId),pay))continue;const commissionBase=(sale.items||[]).filter(i=>!i.productId).reduce((n,i)=>n+(Number(i.price)||0),0),lineCommission=commissionBase?Number((commissionFor(sale)*(Number(item.price)||0)/commissionBase).toFixed(2)):0;sales.push({sale,item,service,barber,commission:lineCommission})}}
  const purchaseExpenseIds=new Set(db.stockMovements.filter(m=>m.type==='شراء'&&(!f.consumableId||m.consumableId===f.consumableId)).map(m=>m.expenseId).filter(Boolean));
  const expenses=db.expenses.filter(e=>reportDateInRange(e.date)&&(!f.payment||e.payment===f.payment)&&(!f.consumableId||purchaseExpenseIds.has(e.id))&&reportSearchMatches(q,e.title,e.category,e.note,e.payment==='cash'?'نقدي':e.payment==='wallet'?'محفظة إلكترونية':e.payment==='other'?'أخرى':'بطاقة'));
  const stock=db.stockMovements.filter(m=>reportDateInRange(m.date)&&(!f.consumableId||m.consumableId===f.consumableId)&&(!f.serviceId||m.serviceId===f.serviceId)&&reportSearchMatches(q,consumableName(m.consumableId),m.serviceId?serviceName(m.serviceId):'',m.type,m.note));
  const payouts=db.payouts.filter(p=>reportDateInRange(p.date)&&(!f.barberId||p.barberId===f.barberId)&&(!f.payment||p.payment===f.payment)&&reportSearchMatches(q,barberName(p.barberId),p.note,p.payment==='cash'?'نقدي':p.payment==='wallet'?'محفظة إلكترونية':p.payment==='other'?'أخرى':'بطاقة'));
  const closes=db.closes.filter(c=>reportDateInRange(c.date));return{sales,expenses,stock,payouts,closes}}
function reportSalesTable(rows){if(!rows.length)return'<div class="empty-state">لا توجد خدمات مطابقة للفلاتر</div>';return `<div class="table-wrap"><table class="data-table"><thead><tr><th>التاريخ والوقت</th><th>العميل / الهاتف</th><th>الخدمة</th><th>الحلاق</th><th>الكرسي</th><th>السعر</th><th>أتعاب الحلاق</th><th>الدفع</th></tr></thead><tbody>${rows.slice().sort((a,b)=>b.sale.createdAt.localeCompare(a.sale.createdAt)).map(r=>`<tr><td>${dateFmt(r.sale.date)} · ${timeFmt(r.sale.createdAt)}</td><td>${esc(r.sale.client||'عميل نقدي')}<small class="muted" style="display:block">${esc(r.sale.clientPhone||'')}</small></td><td>${esc(r.service?.name||'خدمة محذوفة')}</td><td>${esc(r.barber)}</td><td>${esc(chairName(r.sale.chairId))}</td><td>${money(r.item.price)}</td><td>${money(r.commission)}</td><td>${r.sale.payment==='cash'?'نقدي':r.sale.payment==='card'?'بطاقة':r.sale.payment==='wallet'?'محفظة إلكترونية':'أخرى'}</td></tr>`).join('')}</tbody></table></div>`}
function reportExpensesTable(rows){if(!rows.length)return'<div class="empty-state">لا توجد مصروفات مطابقة للفلاتر</div>';return `<div class="table-wrap"><table class="data-table"><thead><tr><th>التاريخ</th><th>المصروف</th><th>التصنيف</th><th>طريقة الدفع</th><th>المبلغ</th><th>ملاحظات</th></tr></thead><tbody>${rows.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(e=>`<tr><td>${dateFmt(e.date)}</td><td>${esc(e.title)}</td><td>${esc(e.category)}</td><td>${e.payment==='cash'?'نقدي':e.payment==='wallet'?'محفظة إلكترونية':e.payment==='other'?'أخرى':'بطاقة'}</td><td class="amount">${money(e.amount)}</td><td>${esc(e.note||'—')}</td></tr>`).join('')}</tbody></table></div>`}
function reportStockTable(rows){if(!rows.length)return'<div class="empty-state">لا توجد حركات مخزون مطابقة للفلاتر</div>';return `<div class="table-wrap"><table class="data-table"><thead><tr><th>التاريخ</th><th>الحركة</th><th>المستهلك</th><th>الخدمة</th><th>الكمية</th><th>القيمة</th><th>ملاحظة</th></tr></thead><tbody>${rows.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(m=>`<tr><td>${dateFmt(m.date)}</td><td>${esc(m.type)}</td><td>${esc(consumableName(m.consumableId))}</td><td>${esc(m.serviceId?serviceName(m.serviceId):'—')}</td><td>${m.quantity} ${esc(db.consumables.find(c=>c.id===m.consumableId)?.unit||'')}</td><td>${money(m.amount||0)}</td><td>${esc(m.note||'—')}</td></tr>`).join('')}</tbody></table></div>`}
function reportPayoutsTable(rows){if(!rows.length)return'<div class="empty-state">لا توجد صرفيات أتعاب مطابقة للفلاتر</div>';return `<div class="table-wrap"><table class="data-table"><thead><tr><th>التاريخ</th><th>الحلاق</th><th>الفترة</th><th>طريقة الدفع</th><th>المبلغ</th><th>ملاحظة</th></tr></thead><tbody>${rows.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(p=>`<tr><td>${dateFmt(p.date)}</td><td>${esc(barberName(p.barberId))}</td><td>${esc(p.period||p.date.slice(0,7))}</td><td>${p.payment==='cash'?'نقدي':p.payment==='wallet'?'محفظة إلكترونية':p.payment==='other'?'أخرى':'بطاقة / تحويل'}</td><td class="amount">${money(p.amount)}</td><td>${esc(p.note||'—')}</td></tr>`).join('')}</tbody></table></div>`}
function reportFiltersPanel(){return `<div class="card panel report-filters"><div class="panel-header"><div><h2>فلاتر التقرير</h2><p>اختر فترة أو حلاقًا أو خدمة أو مستهلكًا، أو ابحث بالاسم والملاحظات والهاتف.</p></div></div><div class="form-grid report-filter-grid"><div class="field"><label>من تاريخ</label><input class="input" type="date" id="reportFrom" value="${esc(reportFilters.from)}" /></div><div class="field"><label>إلى تاريخ</label><input class="input" type="date" id="reportTo" value="${esc(reportFilters.to)}" /></div><div class="field"><label>الحلاق</label><select class="select" id="reportBarber"><option value="">كل الحلاقين</option>${db.barbers.map(b=>`<option value="${b.id}" ${reportFilters.barberId===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></div><div class="field"><label>الخدمة</label><select class="select" id="reportService"><option value="">كل الخدمات</option>${db.services.map(s=>`<option value="${s.id}" ${reportFilters.serviceId===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div><div class="field"><label>المستهلك</label><select class="select" id="reportConsumable"><option value="">كل المستهلكات</option>${db.consumables.map(c=>`<option value="${c.id}" ${reportFilters.consumableId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>طريقة الدفع للمبيعات والمصروفات</label><select class="select" id="reportPayment"><option value="">كل الطرق</option><option value="cash" ${reportFilters.payment==='cash'?'selected':''}>نقدي</option><option value="card" ${reportFilters.payment==='card'?'selected':''}>بطاقة / تحويل</option><option value="wallet" ${reportFilters.payment==='wallet'?'selected':''}>محفظة</option><option value="other" ${reportFilters.payment==='other'?'selected':''}>أخرى</option></select></div><div class="field full"><label>بحث في التفاصيل</label><input class="input" id="reportQuery" value="${esc(reportFilters.query)}" placeholder="عميل، هاتف، اسم مستهلك، خدمة، حلاق، ملاحظة..." /></div></div><div class="inline-add" style="margin-top:12px"><button class="btn btn-primary" data-action="apply-report-filters">تطبيق الفلاتر</button><button class="btn" data-action="reset-report-filters">عرض كل البيانات</button><button class="btn" data-action="export-csv">⇩ تصدير النتائج CSV</button><button class="btn" data-action="print-report">طباعة التقرير</button></div></div>`}
function readReportFilters(){const from=document.getElementById('reportFrom')?.value||'',to=document.getElementById('reportTo')?.value||'';if(from&&to&&from>to){toast('تاريخ البداية يجب أن يكون قبل تاريخ النهاية');return false}reportFilters={from,to,barberId:document.getElementById('reportBarber')?.value||'',serviceId:document.getElementById('reportService')?.value||'',consumableId:document.getElementById('reportConsumable')?.value||'',payment:document.getElementById('reportPayment')?.value||'',query:document.getElementById('reportQuery')?.value.trim()||''};return true}
function applyReportFilters(){if(readReportFilters())render()}
function resetReportFilters(){reportFilters={from:'',to:'',barberId:'',serviceId:'',consumableId:'',payment:'',query:''};render()}
function reportsPage(){const d=buildReportData(),saleIds=new Set(d.sales.map(r=>r.sale.id)),gross=d.sales.reduce((a,r)=>a+(Number(r.item.price)||0),0),comm=d.sales.reduce((a,r)=>a+r.commission,0),expenses=expenseTotal(d.expenses),serviceCounts=new Map();d.sales.forEach(r=>serviceCounts.set(r.service?.name||'خدمة محذوفة',(serviceCounts.get(r.service?.name||'خدمة محذوفة')||0)+1));const dailyMap=new Map();d.sales.forEach(r=>dailyMap.set(r.sale.date,(dailyMap.get(r.sale.date)||0)+(Number(r.item.price)||0)));const daily=[...dailyMap].sort((a,b)=>a[0].localeCompare(b[0])).slice(-24),max=Math.max(1,...daily.map(x=>x[1])),period=`${reportFilters.from||'كل الفترات'} — ${reportFilters.to||'كل الفترات'}`;return `${pageHead('التقارير','فلتر البيانات بالتاريخ والحلاق والخدمة والمستهلك، ثم صدّر التفاصيل.',`<span class="tag">${esc(period)}</span>`)}${reportFiltersPanel()}<div class="grid stats-grid">${stat('إيراد الخدمات المطابقة',money(gross),'↗',`${saleIds.size} عملية · ${d.sales.length} خدمة`)}${stat('أتعاب الخدمات المطابقة',money(comm),'♙','حسب الخدمات الظاهرة')}${stat('مصروفات الفترة',money(expenses),'↙',`${d.expenses.length} بند · لا تُنسب لحلاق معين`)}${stat('صافي الفترة العام',money(gross-comm-expenses),'◈','إيراد النتائج − الأتعاب − مصروفات النتائج')}</div><div class="grid dashboard-grid"><div class="card chart-card"><div class="chart-head"><div><h2 style="font-size:12px;margin:0">الإيراد حسب اليوم</h2><p class="muted" style="font-size:8px">${esc(period)}</p></div><span class="tag">${money(gross)}</span></div><div class="chart-area"><div class="chart-y"><span>${money(max)}</span><span>${money(max*.67)}</span><span>${money(max*.33)}</span><span>٠</span></div><div class="bars">${daily.map(([date,total])=>`<div class="bar-group"><span class="bar ${total===Math.max(...daily.map(x=>x[1]))&&total>0?'emphasis':''}" style="height:${Math.max(2,total/max*100)}%" title="${date}: ${money(total)}"></span><span class="bar-label">${date.slice(8)}</span></div>`).join('')}</div></div></div><div class="card panel"><div class="panel-header"><div><h2>ملخص النتائج</h2><p>إحصاءات للخدمات المطابقة للفلاتر</p></div></div><div class="activity-list"><div class="activity-row" style="grid-template-columns:1fr auto"><span>عدد العملاء</span><b>${[...new Set(d.sales.map(r=>r.sale.id))].reduce((n,id)=>{const s=d.sales.find(x=>x.sale.id===id)?.sale;return n+(s?.customers||1)},0)}</b></div><div class="activity-row" style="grid-template-columns:1fr auto"><span>متوسط قيمة العملية</span><b>${money(saleIds.size?Math.round(gross/saleIds.size):0)}</b></div><div class="activity-row" style="grid-template-columns:1fr auto"><span>نقدي</span><b>${money(d.sales.filter(r=>r.sale.payment==='cash').reduce((a,r)=>a+(Number(r.item.price)||0),0))}</b></div><div class="activity-row" style="grid-template-columns:1fr auto"><span>غير نقدي</span><b>${money(d.sales.filter(r=>r.sale.payment!=='cash').reduce((a,r)=>a+(Number(r.item.price)||0),0))}</b></div><div class="activity-row" style="grid-template-columns:1fr auto"><span>استهلاك مخزون</span><b>${d.stock.filter(m=>m.type==='استهلاك').reduce((a,m)=>a+Number(m.quantity||0),0)}</b></div></div></div></div><div class="card panel" style="margin-top:15px"><div class="panel-header"><div><h2>تفاصيل الخدمات والمبيعات</h2><p>سطر مستقل لكل خدمة داخل الفاتورة</p></div><span class="tag">${d.sales.length} خدمة</span></div>${reportSalesTable(d.sales)}</div><div class="card panel" style="margin-top:15px"><div class="panel-header"><div><h2>تفاصيل المصروفات</h2><p>تشمل مشتريات المستهلكات كمصروف عند الشراء</p></div><span class="tag">${d.expenses.length} بند</span></div>${reportExpensesTable(d.expenses)}</div><div class="card panel" style="margin-top:15px"><div class="panel-header"><div><h2>حركة المستهلكات</h2><p>شراء وإضافة للمخزون أو استهلاك مرتبط بالخدمة</p></div><span class="tag">${d.stock.length} حركة</span></div>${reportStockTable(d.stock)}</div><div class="card panel" style="margin-top:15px"><div class="panel-header"><div><h2>صرف أتعاب الحلاقين</h2><p>السجلات المطابقة للتاريخ والحلاق والدفع والبحث</p></div><span class="tag">${d.payouts.length} عملية</span></div>${reportPayoutsTable(d.payouts)}</div><div class="card panel" style="margin-top:15px"><div class="panel-header"><div><h2>أداء الحلاقين في النتائج</h2><p>محسوب من الخدمات التي طابقت الفلاتر</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>الحلاق</th><th>عدد العمليات</th><th>الخدمات</th><th>الإيراد المطابق</th><th>الأتعاب</th></tr></thead><tbody>${db.barbers.filter(b=>!reportFilters.barberId||b.id===reportFilters.barberId).map(b=>{const rows=d.sales.filter(r=>r.sale.barberId===b.id);return `<tr><td>${esc(b.name)}</td><td>${new Set(rows.map(r=>r.sale.id)).size}</td><td>${rows.length}</td><td>${money(rows.reduce((a,r)=>a+(Number(r.item.price)||0),0))}</td><td>${money(rows.reduce((a,r)=>a+r.commission,0))}</td></tr>`}).join('')||'<tr><td colspan="5">لا توجد بيانات</td></tr>'}</tbody></table></div></div><div class="card panel" style="margin-top:15px"><div class="panel-header"><div><h2>إقفال الأيام</h2><p>الإقفالات الواقعة في الفترة المحددة</p></div></div>${closeTable(d.closes)}</div>`}
function closeTable(rows){if(!rows.length)return'<div class="empty-state">لم يتم إقفال أي يوم في الفترة</div>';return `<div class="table-wrap"><table class="data-table"><thead><tr><th>التاريخ</th><th>المبيعات</th><th>المصروفات</th><th>أتعاب مستحقة</th><th>أتعاب مدفوعة نقدًا</th><th>المتوقع في الدرج</th><th>الفعلي</th><th>الفرق</th></tr></thead><tbody>${rows.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(c=>`<tr><td>${dateFmt(c.date)}</td><td>${money(c.sales)}</td><td>${money(c.expenses)}</td><td>${money(c.commissions)}</td><td>${money(c.barberPayoutsCash||0)}</td><td>${money(c.expected)}</td><td>${money(c.actual)}</td><td>${money(c.actual-c.expected)}</td></tr>`).join('')}</tbody></table></div>`}
function settingsPage(){return `${pageHead('الإعدادات','خصص بيانات المحل والعملة والإعدادات الافتراضية.')}<div class="card panel"><div class="panel-header"><div><h2>قاعدة بيانات Excel</h2><p>يحفظ التطبيق بيانات المحل تلقائيًا داخل ملف Excel في مجلد المشروع.</p></div><span id="excelStatusText" class="excel-card-status ${excelSyncing?'ok':''}">${excelSyncing?'Excel محفوظ':'Excel غير مربوط'}</span></div><div class="excel-card"><div><strong>Database.xlsx</strong><p>اربط الملف الموجود داخل مجلد Database أول مرة. اترك الملف مغلقًا في Excel أثناء تشغيل التطبيق حتى يقدر يحفظ التعديلات.</p></div><div class="inline-add"><button class="btn" data-action="sync-excel">حفظ الآن</button><button class="btn btn-primary" data-action="connect-excel">${excelHandle?'إعادة ربط الملف':'ربط ملف Database.xlsx'}</button></div></div><p class="muted" style="font-size:8px">نسخة الجهاز المحلية تظل موجودة أيضًا، وتُستخدم لاسترجاع آخر تغيير إذا أُغلق التطبيق قبل اكتمال حفظ Excel.</p></div><div class="grid dashboard-grid" style="margin-top:15px"><div class="card panel"><div class="panel-header"><h2>بيانات المحل</h2></div><div class="form-grid"><div class="field full"><label>اسم المحل</label><input class="input" id="shopSetting" value="${esc(db.settings.shop)}" /></div><div class="field"><label>العملة</label><select id="currencySetting" class="select">${['ج.م','ر.س','د.إ','د.ك','د.ب','ر.ق','د.أ','ل.س','د.م','د.ع'].map(c=>`<option ${db.settings.currency===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label>نسبة العمولة الافتراضية (%)</label><input class="input" id="defaultCommission" type="number" min="0" max="100" value="${db.settings.commission}" /></div></div><button class="btn btn-primary" data-action="save-settings" style="margin-top:15px">حفظ الإعدادات</button></div><div class="card panel"><div class="panel-header"><h2>النسخ الاحتياطي</h2></div><div class="modal-note">النسخ اليومية تُحفظ داخل مجلد Backups بجوار مجلد Database. اختر مجلد المشروع مرة واحدة لتفعيلها.</div><div id="backupStatusText" class="backup-status">${backupDirectory?'النسخ اليومي مفعّل':'لم يتم اختيار مجلد النسخ اليومي'}</div><div class="inline-add" style="margin-top:10px"><button class="btn btn-primary" data-action="backup-folder">${backupDirectory?'تغيير مجلد النسخ':'اختيار مجلد النسخ اليومي'}</button><button class="btn" data-action="restore-excel">استعادة نسخة Excel</button></div><div class="modal-note">يمكنك أيضًا تنزيل أو استعادة نسخة JSON يدويًا.</div><button class="btn" data-action="backup">⇩ تنزيل نسخة JSON</button> <button class="btn" data-action="restore">⇧ استعادة نسخة JSON</button><input type="file" id="restoreFile" accept="application/json" hidden /><div class="modal-note">قاعدة البيانات الحالية تحتوي على <b>${db.sales.length} مبيعات</b>، <b>${db.expenses.length} مصروفات</b>، <b>${db.barbers.length} حلاقين</b> و<b>${db.payouts.length} صرفيات أتعاب</b>.</div></div></div><div class="card panel" style="margin-top:15px"><div class="panel-header"><h2>إدارة البيانات</h2></div><p class="muted" style="font-size:9px;line-height:2">النظام مخصص للاستخدام المحلي على هذا الجهاز، ولا يرسل بياناتك إلى الإنترنت. مسح البيانات إجراء نهائي.</p><button class="btn btn-danger" data-action="reset-data">مسح كل البيانات</button></div>`}
function usersPage(){return `${pageHead('المستخدمين','أنشئ حسابات الكاشير وحدد من يستطيع الدخول للتطبيق.',`<button class="btn btn-primary" data-action="add-cashier">＋ إضافة كاشير</button>`)}${cashierUsersCard()}`}function cashierUsersCard(){return `<div class="card panel" style="margin-top:15px"><div class="panel-header"><div><h2>حسابات المستخدمين</h2><p>المدير يدخل بحساب manager، والكاشير يدخل بحسابه بصلاحيات محدودة.</p></div></div>${appUsers.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>الاسم</th><th>اسم المستخدم</th><th>الصلاحية</th><th>الحالة</th><th></th></tr></thead><tbody>${appUsers.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.username)}</td><td>كاشير</td><td><span class="tag ${u.active?'':'gray'}">${u.active?'نشط':'موقوف'}</span></td><td><button class="btn btn-small" data-user-toggle="${u.id}">${u.active?'إيقاف':'تفعيل'}</button> <button class="btn btn-small btn-danger" data-user-delete="${u.id}">حذف</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">لا توجد حسابات كاشير. أضف حسابًا للبدء.</div>'}<div class="hint">حسابات المستخدمين محفوظة على هذا الجهاز داخل ملف تعريف Edge. عند نقل التطبيق لجهاز آخر، أنشئ حسابات الكاشير من جديد.</div></div>`}
function cashierUserModal(){if(!requireManager())return;showModal('إضافة حساب كاشير',`<form id="entityForm"><div class="form-grid"><div class="field"><label>اسم الكاشير</label><input class="input" name="name" required /></div><div class="field"><label>اسم المستخدم</label><input class="input" name="username" autocomplete="off" required minlength="3" placeholder="مثال: cashier1" /></div><div class="field"><label>كلمة المرور</label><input class="input" name="password" type="password" required  autocomplete="new-password" /></div><div class="field"><label>تأكيد كلمة المرور</label><input class="input" name="confirm" type="password" required  autocomplete="new-password" /></div></div></form><div class="modal-note">الكاشير يقدر يسجل المبيعات ويتابع الحجوزات والعملاء. الإعدادات والمخزون والمصروفات والتقارير والإقفال للمدير فقط.</div>`,`<button class="btn" onclick="closeModal()">إلغاء</button><button class="btn btn-primary" id="saveCashier">إنشاء الحساب</button>`);document.getElementById('saveCashier').onclick=async()=>{const f=new FormData(document.getElementById('entityForm')),name=String(f.get('name')||'').trim(),username=String(f.get('username')||'').trim().toLowerCase(),password=String(f.get('password')||'');if(!name||!/^[a-z0-9._-]{3,32}$/.test(username)||username==='admin')return toast('استخدم اسم مستخدم من ٣ إلى ٣٢ حرفًا إنجليزيًا أو رقمًا، ولا تستخدم manager');if(appUsers.some(u=>u.username.toLowerCase()===username))return toast('اسم المستخدم مستخدم بالفعل');if(!password)return toast('اكتب كلمة المرور');if(password!==f.get('confirm'))return toast('كلمتا المرور غير متطابقتين');const salt=hexBytes(crypto.getRandomValues(new Uint8Array(16))),hash=await passwordDigest(password,salt);appUsers.push({id:uid(),name,username,role:'cashier',salt,hash,active:true,createdAt:new Date().toISOString()});saveUsers();closeModal();render();toast('تم إنشاء حساب الكاشير')};}
function toggleCashierUser(id){if(!requireManager())return;const u=appUsers.find(x=>x.id===id);if(!u)return;u.active=!u.active;saveUsers();render()}
function deleteCashierUser(id){if(!requireManager())return;const u=appUsers.find(x=>x.id===id);if(!u)return;if(confirm(`حذف حساب ${u.name}؟`)){appUsers=appUsers.filter(x=>x.id!==id);saveUsers();render()}}function wirePage(){const p=document.getElementById('page');p.querySelectorAll('[data-user-toggle]').forEach(b=>b.onclick=()=>toggleCashierUser(b.dataset.userToggle));p.querySelectorAll('[data-user-delete]').forEach(b=>b.onclick=()=>deleteCashierUser(b.dataset.userDelete));p.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>action(b.dataset.action)));const excelIndicator=document.getElementById('excelIndicator');if(excelIndicator)excelIndicator.onclick=()=>go('settings');p.querySelectorAll('[data-add-service]').forEach(b=>b.addEventListener('click',()=>{if(db.closes.some(c=>c.date===today))return toast('الكاشير مغلق اليوم');const s=db.services.find(x=>x.id===b.dataset.addService);cart.push({serviceId:s.id,name:s.name,price:Number(s.price)});refreshCart()}));p.querySelectorAll('[data-remove-item]').forEach(b=>b.addEventListener('click',()=>{cart.splice(Number(b.dataset.removeItem),1);refreshCart()}));p.querySelectorAll('[data-edit-barber]').forEach(b=>b.onclick=()=>barberModal(b.dataset.editBarber));p.querySelectorAll('[data-payout-barber]').forEach(b=>b.onclick=()=>payoutModal(b.dataset.payoutBarber));p.querySelectorAll('[data-edit-service]').forEach(b=>b.onclick=()=>serviceModal(b.dataset.editService));p.querySelectorAll('[data-recipe-service]').forEach(b=>b.onclick=()=>recipeModal(b.dataset.recipeService));p.querySelectorAll('[data-edit-consumable]').forEach(b=>b.onclick=()=>consumableModal(b.dataset.editConsumable));p.querySelectorAll('[data-edit-chair]').forEach(b=>b.onclick=()=>chairModal(b.dataset.editChair));p.querySelectorAll('[data-customer-history]').forEach(b=>b.onclick=()=>customerHistory(b.dataset.customerHistory));p.querySelectorAll('[data-delete-expense]').forEach(b=>b.onclick=()=>{if(confirm('حذف المصروف؟')){db.expenses=db.expenses.filter(x=>x.id!==b.dataset.deleteExpense);save();render()}});p.querySelectorAll('[data-complete-appt]').forEach(b=>b.onclick=()=>completeAppointment(b.dataset.completeAppt));p.querySelectorAll('[data-cancel-appt]').forEach(b=>b.onclick=()=>{const a=db.appointments.find(x=>x.id===b.dataset.cancelAppt);a.status='cancelled';save();render()});const search=document.getElementById('serviceSearch');if(search)search.oninput=()=>{const q=search.value.trim().toLowerCase();document.querySelectorAll('.service-tile').forEach(t=>t.hidden=!t.innerText.toLowerCase().includes(q))};const customerSearch=document.getElementById('customerSearch');if(customerSearch)customerSearch.oninput=()=>{const q=customerSearch.value.trim().toLowerCase();document.querySelectorAll('.history-row').forEach(t=>t.hidden=!t.innerText.toLowerCase().includes(q))};const month=document.getElementById('reportMonth')||document.getElementById('barberMonth');if(month)month.onchange=()=>{reportMonth=month.value||today.slice(0,7);render()};const em=document.getElementById('expenseMonth');if(em)em.onchange=()=>{document.getElementById('expenseTable').innerHTML=expenseTable(em.value==='all'?db.expenses:db.expenses.filter(e=>e.date.startsWith(em.value)));wireExpenseDelete()};const restore=document.getElementById('restoreFile');if(restore)restore.onchange=restoreBackup}
function wireExpenseDelete(){document.querySelectorAll('[data-delete-expense]').forEach(b=>b.onclick=()=>{if(confirm('حذف المصروف؟')){db.expenses=db.expenses.filter(x=>x.id!==b.dataset.deleteExpense);save();render()}})}
function refreshCart(){const rows=document.getElementById('cartRows');if(!rows)return;rows.innerHTML=cartHtml();rows.querySelectorAll('[data-remove-item]').forEach(b=>b.onclick=()=>{cart.splice(Number(b.dataset.removeItem),1);refreshCart()});const total=money(cart.reduce((a,i)=>a+i.price,0));document.querySelector('.order-total strong').textContent=total;document.querySelector('[data-action="checkout"]').textContent='تأكيد البيع · '+total}
function action(a){if(!isManager()&&!['go-cashier','clear-cart','checkout','new-appointment'].includes(a))return requireManager();switch(a){case'connect-excel':return connectExcel();case'sync-excel':return syncExcelNow();case'backup-folder':return chooseBackupFolder();case'restore-excel':return restoreExcelBackup();case'go-cashier':return go('cashier');case'go-barbers':return go('barbers');case'go-chairs':return go('chairs');case'clear-cart':cart=[];render();return;case'checkout':return checkout();case'close-day':return closeDayModal();case'add-barber':return barberModal();case'add-service':return serviceModal();case'add-consumable':return consumableModal();case'purchase-consumable':return purchaseConsumableModal();case'add-chair':return chairModal();case'add-cashier':return cashierUserModal();case'add-expense':return expenseModal();case'new-appointment':return appointmentModal();case'apply-report-filters':return applyReportFilters();case'reset-report-filters':return resetReportFilters();case'export-csv':return exportCsv();case'print-report':return window.print();case'backup':return backup();case'restore':document.getElementById('restoreFile')?.click();return;case'save-settings':db.settings.shop=document.getElementById('shopSetting').value.trim()||'كربيجي';db.settings.currency=document.getElementById('currencySetting').value;db.settings.commission=Math.max(0,Math.min(100,Number(document.getElementById('defaultCommission').value)||0));save();toast('تم حفظ الإعدادات');return render();case'reset-data':if(confirm('سيتم حذف كل البيانات نهائيًا. هل أنت متأكد؟')){db=structuredClone(initial);save();cart=[];go('dashboard')}return}}
function checkout(){if(db.closes.some(c=>c.date===today))return toast('الكاشير مغلق اليوم');if(!cart.length)return toast('أضف خدمة للفاتورة أولًا');const barberId=document.getElementById('saleBarber').value,chairId=document.getElementById('saleChair').value;if(!barberId)return toast('اختر الحلاق');if(!chairId)return toast('اختر الكرسي');const barber=db.barbers.find(b=>b.id===barberId),sale={id:uid(),date:today,createdAt:new Date().toISOString(),client:document.getElementById('clientName').value.trim()||'عميل نقدي',clientPhone:document.getElementById('clientPhone').value.trim(),barberId,chairId,payment:document.getElementById('salePayment').value,items:cart.map(i=>({serviceId:i.serviceId,price:i.price})),total:cart.reduce((a,i)=>a+i.price,0),commission:barber.commission,customers:1};const stockCheck=canConsumeForSale(sale.items);if(!stockCheck.ok)return toast(stockCheck.message);consumeForSale(sale.items,sale);db.sales.push(sale);save();cart=[];toast('تم تسجيل عملية البيع بنجاح');render()}
function showModal(title,body,footer=''){document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop" id="backdrop"><div class="modal"><div class="modal-head"><h2>${title}</h2><button class="modal-close" id="modalX">×</button></div>${body}${footer?`<div class="modal-actions">${footer}</div>`:''}</div></div>`;document.getElementById('modalX').onclick=closeModal;document.getElementById('backdrop').onclick=e=>{if(e.target.id==='backdrop')closeModal()}}
function closeModal(){document.getElementById('modalRoot').innerHTML=''}
function closeAction(label){return `<button class="btn btn-primary" onclick="closeModal()">${label}</button>`}
function barberModal(id){const b=db.barbers.find(x=>x.id===id)||{name:'',phone:'',commission:db.settings.commission,active:true};showModal(id?'تعديل بيانات الحلاق':'إضافة حلاق',`<form id="entityForm"><div class="form-grid"><div class="field full"><label>اسم الحلاق *</label><input name="name" class="input" required value="${esc(b.name)}" /></div><div class="field"><label>رقم الهاتف</label><input name="phone" class="input" value="${esc(b.phone)}" /></div><div class="field"><label>نسبة الأتعاب (%)</label><input name="commission" class="input" type="number" min="0" max="100" required value="${b.commission}" /></div><div class="field full"><label class="inline-add"><input name="active" type="checkbox" ${b.active?'checked':''}/> الحلاق نشط</label></div></div></form>`,`<button class="btn" onclick="closeModal()">إلغاء</button><button class="btn btn-primary" id="saveEntity">حفظ</button>`);document.getElementById('saveEntity').onclick=()=>{const f=new FormData(document.getElementById('entityForm'));if(!f.get('name').trim())return;const data={id:id||uid(),name:f.get('name').trim(),phone:f.get('phone').trim(),commission:Math.min(100,Math.max(0,Number(f.get('commission')))),active:f.has('active')};if(id)Object.assign(b,data);else db.barbers.push(data);save();closeModal();render();toast('تم حفظ بيانات الحلاق') }}
function serviceModal(id){const s=db.services.find(x=>x.id===id)||{name:'',price:'',minutes:30,active:true};showModal(id?'تعديل الخدمة':'إضافة خدمة',`<form id="entityForm"><div class="form-grid"><div class="field full"><label>اسم الخدمة *</label><input name="name" class="input" required value="${esc(s.name)}" /></div><div class="field"><label>السعر *</label><input name="price" type="number" min="0" class="input" required value="${s.price}" /></div><div class="field"><label>المدة (دقيقة)</label><input name="minutes" type="number" min="1" class="input" value="${s.minutes}" /></div><div class="field full"><label class="inline-add"><input name="active" type="checkbox" ${s.active?'checked':''}/> متاحة على الكاشير</label></div></div></form>`,`<button class="btn" onclick="closeModal()">إلغاء</button><button class="btn btn-primary" id="saveEntity">حفظ</button>`);document.getElementById('saveEntity').onclick=()=>{const f=new FormData(document.getElementById('entityForm'));if(!f.get('name').trim()||!f.get('price'))return;const data={id:id||uid(),name:f.get('name').trim(),price:Number(f.get('price')),minutes:Number(f.get('minutes'))||30,active:f.has('active')};if(id)Object.assign(s,data);else db.services.push(data);save();closeModal();render();toast('تم حفظ الخدمة')}}
function chairModal(id){const c=db.chairs.find(x=>x.id===id)||{name:'',active:true};showModal(id?'تعديل الكرسي':'إضافة كرسي',`<form id="entityForm"><div class="form-grid"><div class="field full"><label>اسم أو رقم الكرسي *</label><input name="name" class="input" required value="${esc(c.name)}" placeholder="مثال: كرسي ٥" /></div><div class="field full"><label class="inline-add"><input name="active" type="checkbox" ${c.active?'checked':''}/> الكرسي نشط</label></div></div></form>`,`<button class="btn" onclick="closeModal()">إلغاء</button><button class="btn btn-primary" id="saveEntity">حفظ</button>`);document.getElementById('saveEntity').onclick=()=>{const f=new FormData(document.getElementById('entityForm'));if(!f.get('name').trim())return;const data={id:id||uid(),name:f.get('name').trim(),active:f.has('active')};if(id)Object.assign(c,data);else db.chairs.push(data);save();closeModal();render();toast('تم حفظ الكرسي')}}
function expenseModal(){if(db.closes.some(c=>c.date===today))return toast('تم إقفال اليوم، لا يمكن تسجيل مصروف جديد بتاريخ اليوم');showModal('تسجيل مصروف',`<form id="entityForm"><div class="form-grid"><div class="field full"><label>اسم المصروف *</label><input name="title" class="input" required placeholder="مثال: مستلزمات حلاقة" /></div><div class="field"><label>المبلغ *</label><input name="amount" type="number" min="1" class="input" required /></div><div class="field"><label>التصنيف</label><select name="category" class="select"><option>مستهلكات</option><option>مستلزمات</option><option>إيجار</option><option>كهرباء ومياه</option><option>رواتب</option><option>صيانة</option><option>أخرى</option></select></div><div class="field"><label>تاريخ المصروف</label><input name="date" type="date" class="input" value="${today}" required /></div><div class="field"><label>طريقة الدفع</label><select name="payment" class="select"><option value="cash">نقدي</option><option value="card">بطاقة</option></select></div><div class="field full"><label>ملاحظات</label><input name="note" class="input" /></div></div></form>`,`<button class="btn" onclick="closeModal()">إلغاء</button><button class="btn btn-primary" id="saveEntity">حفظ المصروف</button>`);document.getElementById('saveEntity').onclick=()=>{const f=new FormData(document.getElementById('entityForm'));if(!f.get('title').trim()||Number(f.get('amount'))<=0)return;if(f.get('date')===today&&db.closes.some(c=>c.date===today))return toast('اليوم مقفل');db.expenses.push({id:uid(),title:f.get('title').trim(),amount:Number(f.get('amount')),category:f.get('category'),date:f.get('date'),payment:f.get('payment'),note:f.get('note').trim()});save();closeModal();render();toast('تم تسجيل المصروف')}}
function appointmentModal(){showModal('حجز جديد',`<form id="entityForm"><div class="form-grid"><div class="field"><label>اسم العميل *</label><input name="client" class="input" required /></div><div class="field"><label>رقم الهاتف</label><input name="phone" class="input" /></div><div class="field"><label>التاريخ</label><input name="date" class="input" type="date" value="${today}" required /></div><div class="field"><label>الوقت</label><input name="time" class="input" type="time" value="12:00" required /></div><div class="field"><label>الخدمة</label><select name="serviceId" class="select">${db.services.filter(s=>s.active).map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></div><div class="field"><label>الحلاق</label><select name="barberId" class="select">${activeBarbers().map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')}</select></div></div></form>`,`<button class="btn" onclick="closeModal()">إلغاء</button><button class="btn btn-primary" id="saveEntity">حفظ الحجز</button>`);document.getElementById('saveEntity').onclick=()=>{const f=new FormData(document.getElementById('entityForm'));db.appointments.push({id:uid(),client:f.get('client').trim(),phone:f.get('phone').trim(),date:f.get('date'),time:f.get('time'),serviceId:f.get('serviceId'),barberId:f.get('barberId'),status:'booked'});save();closeModal();render();toast('تم تسجيل الحجز')}}
function completeAppointment(id){const a=db.appointments.find(x=>x.id===id);if(!a)return;const s=db.services.find(x=>x.id===a.serviceId),b=db.barbers.find(x=>x.id===a.barberId);if(a.date!==today){a.status='completed';save();render();toast('تم تحديث الحجز كمكتمل');return}if(db.closes.some(c=>c.date===today))return toast('الكاشير مغلق اليوم');if(!s||!b)return toast('الخدمة أو الحلاق المرتبط بالحجز غير موجود');const sale={id:uid(),date:today,createdAt:new Date().toISOString(),client:a.client,clientPhone:a.phone||'',barberId:b.id,chairId:'',payment:'cash',items:[{serviceId:s.id,price:s.price}],total:s.price,commission:b.commission,customers:1},check=canConsumeForSale(sale.items);if(!check.ok)return toast(check.message);consumeForSale(sale.items,sale);db.sales.push(sale);a.status='completed';save();render();toast('تم إنهاء الحجز وتسجيل الخدمة نقدًا')}
function closeDayModal(){if(db.closes.some(c=>c.date===today))return toast('تم إقفال اليوم بالفعل');const sales=todaySales(),expenses=db.expenses.filter(e=>e.date===today),gross=salesTotal(sales),cash=salesTotal(sales.filter(s=>s.payment==='cash')),card=salesTotal(sales.filter(s=>s.payment!=='cash')),cashExp=expenseTotal(expenses.filter(e=>e.payment==='cash')),fees=sales.reduce((a,s)=>a+commissionFor(s),0),cashPayouts=expenseTotal(db.payouts.filter(p=>p.date===today&&p.payment==='cash')),expected=cash-cashExp-cashPayouts;const by=activeBarbers().map(b=>({b,fee:sales.filter(s=>s.barberId===b.id).reduce((a,s)=>a+commissionFor(s),0),clients:sales.filter(s=>s.barberId===b.id).length}));showModal('إقفال يوم '+dateFmt(today),`<div class="close-banner"><div><strong>ملخص درج اليوم</strong><small>راجع الأرقام قبل تثبيت الإقفال</small></div><span class="pill-green">${sales.length} عملية</span></div><div class="table-wrap"><table class="data-table"><tbody><tr><td>إجمالي المبيعات</td><td>${money(gross)}</td></tr><tr><td>نقدي في المبيعات</td><td>${money(cash)}</td></tr><tr><td>مدفوع إلكترونيًا</td><td>${money(card)}</td></tr><tr><td>مصروفات نقدية</td><td>${money(cashExp)}</td></tr><tr><td>صرف أتعاب نقدًا</td><td>${money(cashPayouts)}</td></tr><tr><td>أتعاب مستحقة للحلاقين</td><td>${money(fees)}</td></tr><tr><td><strong>النقد المتوقع في الدرج</strong></td><td><strong>${money(expected)}</strong></td></tr></tbody></table></div><div class="modal-note">${by.map(x=>`${esc(x.b.name)}: ${x.clients} عميل، المستحق ${money(x.fee)}`).join('<br>')||'لا توجد عمليات للحلاقين اليوم'}<br><br>تثبيت الإقفال يمنع تسجيل مبيعات جديدة بتاريخ اليوم.</div><div class="field"><label>النقد الفعلي في الدرج *</label><input id="actualCash" class="input" type="number" min="0" value="${Math.max(0,expected)}" /></div>`,`<button class="btn" onclick="closeModal()">رجوع</button><button class="btn btn-primary" id="confirmClose">تثبيت إقفال اليوم</button>`);document.getElementById('confirmClose').onclick=()=>{const actual=Number(document.getElementById('actualCash').value);if(!Number.isFinite(actual)||actual<0)return toast('أدخل مبلغ النقد الفعلي');db.closes.push({id:uid(),date:today,sales:gross,cash,card,expenses:expenseTotal(expenses),cashExpenses:cashExp,commissions:fees,barberPayoutsCash:cashPayouts,expected,actual,barbers:by.map(x=>({id:x.b.id,name:x.b.name,clients:x.clients,fee:x.fee}))});save();createDailyBackup(true);closeModal();render();toast('تم إقفال اليوم بنجاح')}}
