function restoreBackup(e){const file=e.target.files[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const parsed=JSON.parse(reader.result),data=parsed.data||parsed;if(!data.sales||!data.barbers||!data.services)throw 0;if(!confirm('استعادة هذه النسخة واستبدال البيانات الحالية؟'))return;db=data;db.payouts=db.payouts||[];db.sales.forEach(s=>{s.clientPhone=s.clientPhone||''});save();go('dashboard');toast('تم استعادة البيانات بنجاح')}catch{toast('ملف النسخة الاحتياطية غير صالح')}};reader.readAsText(file)}
